#include <WiFi.h>
#include <HTTPClient.h>

void setup() {
  Serial.begin(115200);
  WiFi.begin("{{ssid}}", "{{password}}");
  while (WiFi.status() != WL_CONNECTED) delay(300);
  HTTPClient http;
  String url = String("{{influx_url}}/api/v2/write?org={{org}}&bucket={{bucket}}");
  http.begin(url);
  http.addHeader("Authorization", "Token {{token}}");
  http.addHeader("Content-Type", "text/plain");
  int code = http.POST(String("{{measurement}} value={{value}}"));
  Serial.println(code);
  http.end();
}

void loop() {}
